from manim import *


class ActionsSpecialThreeDScene(SpecialThreeDScene):
    def __init__(self, **kwargs):
        # SpecialThreeDScene.__init__ uses self.renderer before Scene.__init__ creates it, so in recent
        # Manim versions it stops with an AttributeError once its own settings are stored. Finish as a
        # ThreeDScene, which is what it would do next.
        try:
            super().__init__(**kwargs)
        except AttributeError:
            ThreeDScene.__init__(self, **kwargs)

    def construct(self):
        self.set_camera_to_default_position()

        # Objects
        circle = Circle(radius=1)
        circle.set_stroke(RED)
        circle.set_fill(RED)
        circle.move_to([2, 1, 0])
        vector = Vector(direction=2 * RIGHT + UP)
        vector.set_color(WHITE)
        vector.move_to([0, 0, 0])
        eq = MathTex(r"e^{i\pi} + 1 = 0", font_size=48)
        eq.set_color(WHITE)
        eq.move_to([-3, 2, 0])

        self.add(circle, vector)

        # Animation
        self.play(Write(eq), run_time=1)
        self.move_camera(
            phi=70 * DEGREES,
            theta=-50 * DEGREES,
            added_anims=[Indicate(vector)],
            run_time=2,
        )
        self.move_camera(
            frame_center=circle,
            added_anims=[Indicate(vector)],
            run_time=2,
        )
        self.move_camera(
            frame_center=[0, 0, 0],
            added_anims=[Indicate(vector)],
            run_time=2,
        )
        self.begin_ambient_camera_rotation(rate=20 * DEGREES)
        self.play(Indicate(vector), run_time=4)
        self.stop_ambient_camera_rotation()
        self.begin_3dillusion_camera_rotation()
        self.play(Indicate(vector), run_time=4)
        self.stop_3dillusion_camera_rotation()
